import React from 'react';
import classNames from 'classnames';
import { ThemeAppLogo } from '@getvim/atomic-ui';
import { NotificationsIndicator, ErrorPopover } from '../../atoms';
import { MicrophoneBadge } from '../../atoms/microphone-badge/MicrophoneBadge';
import './index.less';
import { NewMenuItemBadge } from '../../atoms/new-menu-item-badge/NewMenuItemBadge';
import { UI } from '@deprecated/types';

interface ShrunkMenuProps {
  onMouseEnter?: () => void;
  notifications?: number;
  ignoreNotificationsValue?: boolean;
  loading?: boolean;
  inactive?: boolean;
  shrink?: boolean;
  clearNotificationsIndicator?: boolean;
  showNewAppBadge?: boolean;
  hubPosition: UI.HubPosition;
  showMicrophoneBadge?: boolean;
  showErrorPopover?: boolean;
}

export const HubMenuIcon = ({
  onMouseEnter,
  notifications,
  loading,
  inactive,
  shrink,
  clearNotificationsIndicator,
  showNewAppBadge = false,
  showMicrophoneBadge = false,
  hubPosition,
  showErrorPopover = false,
}: ShrunkMenuProps) => {
  return (
    <div data-testid="hub-menu-icon" className={classNames('hub-menu-icon', { shrink })}>
      <div className={classNames('icon-container', 'normal-cursor')} onMouseEnter={onMouseEnter}>
        {notifications !== undefined && !clearNotificationsIndicator ? (
          <NotificationsIndicator value={notifications} inactive={inactive} shrink={shrink} />
        ) : null}
        <ThemeAppLogo loading={loading} inactive={inactive} />
      </div>
      {showNewAppBadge && <NewMenuItemBadge hubPosition={hubPosition} />}
      {showMicrophoneBadge && <MicrophoneBadge hubPosition={hubPosition} />}
      {showErrorPopover && <ErrorPopover />}
    </div>
  );
};
