import React, { useState, useEffect } from 'react';
import { ProgressBar } from '@getvim/atomic-ui';
import { useClipPathObserver } from '@/hub/hooks';
import errorIcon from './errorIcon.svg';
import './ErrorPopover.less';

interface ErrorPopoverProps {
  className?: string;
  duration?: number;
}

export const ErrorPopover: React.FC<ErrorPopoverProps> = ({ className, duration = 5000 }) => {
  const popoverContentRef = useClipPathObserver();
  const [isVisible, setIsVisible] = useState(false);
  const [progress, setProgress] = useState(100);
  const [isPaused, setIsPaused] = useState(false);
  const [showTimeout, setShowTimeout] = useState<NodeJS.Timeout | null>(null);

  useEffect(() => {
    if (!isVisible || isPaused) return;

    const interval = setInterval(() => {
      setProgress((prev) => {
        const newProgress = prev - 100 / (duration / 50); // 50ms intervals
        if (newProgress <= 0) {
          setIsVisible(false);
          return 0;
        }
        return newProgress;
      });
    }, 50);

    return () => clearInterval(interval);
  }, [isVisible, isPaused, duration]);

  const startTimer = () => {
    if (!isVisible) {
      // Clear any existing timeout
      if (showTimeout) {
        clearTimeout(showTimeout);
      }
      // Set a delay before showing the popover
      const timeout = setTimeout(() => {
        setIsVisible(true);
        setProgress(100);
        setIsPaused(false);
      }, 200); // 200ms delay
      setShowTimeout(timeout);
    } else {
      setIsPaused(true);
    }
  };

  const pauseTimer = () => {
    if (isVisible && !isPaused) {
      setIsPaused(true);
    }
  };

  const resumeTimer = () => {
    if (isVisible && isPaused) {
      setIsPaused(false);
    }
  };

  const stopTimer = () => {
    // Clear the show timeout
    if (showTimeout) {
      clearTimeout(showTimeout);
      setShowTimeout(null);
    }
    if (!isVisible) {
      setIsVisible(false);
      setProgress(100);
      setIsPaused(false);
    }
  };

  return (
    <div className="error-popover-wrapper">
      <div className="error-icon-container" onMouseEnter={startTimer} onMouseLeave={stopTimer}>
        <i className="icon-x" />
      </div>

      {isVisible && (
        <div
          className={`error-popover-container ${className}`}
          onMouseEnter={pauseTimer}
          onMouseLeave={resumeTimer}
        >
          <div className="error-popover-content" ref={popoverContentRef}>
            <div className="close-button" onClick={() => setIsVisible(false)}>
              <i className="icon-x" />
            </div>
            <div className="error-image-container">
              <img src={errorIcon} alt="error" />
            </div>
            <div>
              <strong>Vim is temporarily offline due to a technical issue.</strong>
              <br />
              Service will resume shortly.
              <br /> For ongoing updates, please visit{' '}
              <a href="https://status.getvim.com" target="_blank" rel="noopener noreferrer">
                status.getvim.com
              </a>
            </div>
            <div className="error-popover-progress">
              <ProgressBar
                value={progress}
                progressBarStyle="tiny"
                color="main"
                showLabel={false}
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
