import { ClipPathObserver } from '@/hub/services/clipPathObserver';
import { useInjection } from 'inversify-react';
import { useRefEffect } from 'react-use-ref-effect';

export const useClipPathObserver = <T extends HTMLElement = HTMLDivElement>() => {
  const clipPathObserver = useInjection(ClipPathObserver);
  const componentToObserveRef = useRefEffect<T>((element) => {
    const unsubscribe = clipPathObserver.observeBounds(element);

    return () => {
      unsubscribe();
    };
  }, []);

  return componentToObserveRef;
};
